entries[355316] = { ["name"] = "Annhyldes Aegis", ["text"] = "Sofort 1.5 min Abklingzeit\nSchützt Euch mit Annhyldes Aegis, die 8 Sek. lang den Schaden, den Ihr durch Gegner vor Euch erleidet, durch Absorption um 1799 verringert.\n\nSobald 6297 Schaden verhindert wurde, zerspringt der Schild und stößt gebündelte Macht aus, die Gegnern vor Euch 1003 Heiligschaden zufügt." }
