entries[355319] = { ["name"] = "Eine Stimme im Dunklen", ["text"] = "Eine Stimme flüstert Euch zu und zwingt Euch regelmäßig, ihren Anordnungen Folge zu leisten. Wenn Ihr dies tut, werdet Ihr für 20 Sek. mit einer Erhöhung Eures höchsten Sekundärwerts um 191 belohnt." }
