entries[355321] = { ["name"] = "Gequälte Einsicht", ["text"] = "Kanalisiert (Wirken in 2 sek.) 2 min Abklingzeit\nBlickt in die Kugel, was Eure Meisterschaft für bis zu 40 Sek. um 273 erhöht, Euch aber im Verlauf von 2 Sek. ( 1128 * 4) Schattenschaden zufügt. Je länger Ihr hineinblickt, desto mehr werdet Ihr gequält und desto mehr Einsicht erhaltet Ihr." }
