entries[355323] = { ["name"] = "Karaffe des endlosen Heulens", ["text"] = "Ca. 1.5 Procs pro Minute\nEure kritischen Treffer haben eine Chance, Eure Stärke oder Beweglichkeit für 15 Sek. um 144 zu erhöhen. Falls Ihr dabei weniger als 50% Gesundheit habt, werdet Ihr zusätzlich im Verlauf von 6 Sek. um ( 475 * 4) Gesundheit geheilt." }
entries[355324] = { ["name"] = "Streckbankfragment des Peinigers", ["text"] = "Ca. 4 Procs pro Minute\nEure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, im Verlauf von 15 Sek. [Quellwert] zusätzlichen Schattenschaden zu verursachen.\n\nWenn ein Ziel stirbt, während es vom Streckbankfragment des Peinigers betroffen ist, hinterlässt es eine zerfetzte Seele, die Ihr einsammeln könnt, um Euren kritischen Trefferwert für 20 Sek. um 17 zu erhöhen.", ["unresolvedValues"] = true }
