entries[356250] = { ["name"] = "Elementarverbunden", ["text"] = "Runenschnitzmacht\nSofort\nAuf bis zu 5 verbündete Ziele, die mit 'Kettenernte' geheilt wurden, wird 'Springflut' gewirkt. Auf bis zu 5 gegnerische Ziele, denen mit 'Kettenernte' Schaden zugefügt wurde, wird 'Flammenschock' gewirkt. Kritische Treffer mit 'Flammenschock' verringern die Abklingzeit von 'Kettenernte' um 1.0 Sek.\nRunenschnitzen: Brust, Handgelenk\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt." }
